function complexityInputs(){elements.complexityRows.replaceChildren();for(const dimension of complexityDimensions){const row=document.createElement("article"),title=document.createElement("strong"),classification=document.createElement("select"),description=document.createElement("textarea");title.textContent=dimension.replaceAll("-"," ");classification.name=`classification-${dimension}`;classification.required=true;for(const value of ["undetermined","necessary","unnecessary","mixed"]){const option=document.createElement("option");option.value=value;option.textContent=value;classification.append(option);}description.name=`complexity-${dimension}`;description.minLength=20;description.maxLength=1200;description.required=true;description.value=`${dimension.replaceAll("-"," ")} remains undetermined until confidential multi-perspective evidence tests the approved execution demand.`;row.append(title,classification,description);elements.complexityRows.append(row);}}
function renderFrame(frame){elements.frameResult.replaceChildren();if(!frame){elements.frameForm.hidden=false;return;}elements.frameForm.hidden=true;const card=document.createElement("article"),title=document.createElement("strong"),question=document.createElement("p"),detail=document.createElement("p");title.textContent="Approved diagnostic inquiry";question.textContent=frame.diagnosticQuestion;detail.textContent=`${frame.complexityProfile.observations.length} working hypotheses · ${frame.evidencePlan.participantSlots.length} perspective slots · Approved ${new Date(frame.approvedAt).toLocaleString()}`;card.append(title,question,detail);elements.frameResult.append(card);}
function boundedPrefill(value,maximum){const clean=String(value||"").trim();return clean.length<=maximum?clean:`${clean.slice(0,maximum-1).trim()}…`;}
function prefillFrame(context){if(!context)return;const form=elements.frameForm.elements,scope=context.diagnosticScopeName?`System being examined: ${context.diagnosticScopeName} (${context.diagnosticScopeType}). Inside the inquiry: ${context.diagnosticScopeBoundary}. Cross-boundary dependencies: ${context.crossBoundaryDependencies}.\n\n`:"";form.organizationContext.value=boundedPrefill(`${scope}${context.organizationContext}`,2000);form.commitment.value=boundedPrefill(context.strategicPriority,1200);form.failureExposure.value=boundedPrefill(context.decisionsAtRisk||context.triggeringConcern,1200);form.leadershipDecision.value=boundedPrefill(context.decisionNeeded,1000);form.knownSensitivities.value=boundedPrefill(context.knownSensitivities,1200);form.performanceConsequences.value=boundedPrefill(context.triggeringConcern,500);form.outOfScope.value="Individual performance evaluation\nAttribution of comments to participants";form.approvalNote.value="Approved as a bounded v2 Diagnostic Frame for evidence collection and method validation.";requestAnimationFrame(()=>expandNarratives(elements.frameForm));}
