function renderProtocolV2(protocol){elements.protocolV2Result.replaceChildren();elements.protocolV2Finalization.hidden=true;if(!protocol)return;elements.protocolV2Form.hidden=true;const card=document.createElement("article"),title=document.createElement("strong"),detail=document.createElement("p");title.textContent="Participant question set";const state=protocol.stewardFinalizedAt?`Steward-finalized ${new Date(protocol.stewardFinalizedAt).toLocaleString()}`:protocol.sponsorApprovedAt?`Sponsor-approved ${new Date(protocol.sponsorApprovedAt).toLocaleString()} · steward finalization required`:"Awaiting sponsor review";detail.textContent=`${protocol.questions.length} shared questions · ${state}`;card.append(title,detail);elements.protocolV2Result.append(card);elements.protocolV2Finalization.hidden=!(protocol.sponsorApprovedAt&&!protocol.stewardFinalizedAt);}
function renderProtocolV2Draft(draft,policy){elements.protocolV2Questions.replaceChildren();elements.protocolV2Coverage.replaceChildren(...[[draft.questions.length,"core questions"],[new Set(draft.questions.map(q=>q.evidenceLayerId)).size,"evidence layers"],[new Set(draft.questions.flatMap(q=>q.mechanismIds)).size,"mechanisms"]].map(([number,label])=>Object.assign(document.createElement("span"),{textContent:`${number} ${label}`})));for(const question of draft.questions){const card=document.createElement("article"),number=document.createElement("strong"),label=document.createElement("label"),textarea=document.createElement("textarea"),meta=document.createElement("small");card.className="protocol-v2-question";card.dataset.templateId=question.templateId;number.textContent=String(question.position).padStart(2,"0");textarea.value=question.questionText;textarea.minLength=20;textarea.maxLength=600;textarea.required=true;meta.textContent=`Evidence: ${question.evidenceLayerId.replaceAll("-"," ")}${question.mechanismIds.length?` · Mechanisms: ${question.mechanismIds.map(value=>value.replaceAll("-"," ")).join(", ")}`:""}`;label.append(textarea,meta);card.append(number,label);elements.protocolV2Questions.append(card);}elements.protocolV2Form.hidden=false;elements.protocolV2Message.textContent=`Shared core protocol · ${policy.minimumQuestions}–${policy.maximumQuestions} questions allowed · no mechanism score.`;requestAnimationFrame(()=>expandNarratives(elements.protocolV2Form));}
