function renderSynthesis(finding){elements.synthesisResult.replaceChildren();elements.synthesisReview.hidden=true;if(!finding)return;const hypothesis=document.createElement("article");hypothesis.className="synthesis-hypothesis";const title=document.createElement("strong");title.textContent=`Draft constraint hypothesis · ${finding.confidence} confidence`;const statement=document.createElement("p");statement.textContent=finding.hypothesis.statement;const confidence=document.createElement("p");confidence.textContent=`Confidence basis: ${finding.hypothesis.confidenceBasis}`;const direction=document.createElement("p");direction.textContent=`Intervention direction: ${finding.hypothesis.interventionDirection}`;const alternatives=finding.hypothesis.competingExplanations.map(item=>`${item.statement} Evidence needed: ${item.evidenceNeeded}`);hypothesis.append(title,statement,confidence);if(finding.hypothesis.mechanismIds?.length)hypothesis.append(listSection("Mechanisms implicated — not scored",finding.hypothesis.mechanismIds.map(value=>value.replaceAll("-"," "))));hypothesis.append(listSection("Competing explanations",alternatives),listSection("Blind spots",finding.hypothesis.blindSpots));if(finding.hypothesis.uncertaintyStatement){const uncertainty=document.createElement("p");uncertainty.textContent=`Uncertainty: ${finding.hypothesis.uncertaintyStatement}`;hypothesis.append(uncertainty,listSection("Boundary conditions",finding.hypothesis.boundaryConditions));}hypothesis.append(direction);elements.synthesisResult.append(hypothesis);for(const theme of finding.themes){const card=document.createElement("article");card.className="synthesis-theme";const heading=document.createElement("strong");heading.textContent=`${theme.title} · ${theme.confidence}`;const summary=document.createElement("p");summary.textContent=theme.summary;const basis=document.createElement("p");basis.textContent=`Confidence basis: ${theme.confidenceBasis}`;const trace=document.createElement("small");trace.textContent=`Evidence trace: ${theme.supportingEvidenceIds.length} supporting · ${theme.weakeningEvidenceIds.length} weakening${theme.mechanismIds?.length?` · Mechanisms: ${theme.mechanismIds.map(value=>value.replaceAll("-"," ")).join(", ")}`:""}`;card.append(heading,summary,basis,trace);elements.synthesisResult.append(card);}elements.synthesisReview.hidden=finding.advisorReviewStatus!=="pending";elements.synthesisReviewNote.value=finding.advisorReviewNote||"";}
function outputTextSection(title,text){const section=document.createElement("section"),heading=document.createElement("h4"),copy=document.createElement("p");heading.textContent=title;copy.textContent=text||"Not specified in the approved synthesis.";section.append(heading,copy);return section;}
