function outputReviewForm(artifact,reviewStatus){if(reviewStatus!=="pending")return null;const form=document.createElement("form"),label=document.createElement("label"),note=document.createElement("textarea"),actions=document.createElement("div");form.className="diagnostic-output-review";form.dataset.outputReview=artifact;label.textContent="Steward review note";note.name="reviewNote";note.maxLength=1200;note.placeholder="Record any caution, sensitive wording concern, or approval rationale.";for(const[decision,text]of[["approved","Approve output"],["revision-required","Request revision"]]){const button=document.createElement("button");button.type="submit";button.name="decision";button.value=decision;button.textContent=text;button.className=decision==="approved"?"primary-button":"text-button";actions.append(button);}form.append(label,note,actions);return form;}
