function renderDiagnosticOutputs(outputs){elements.diagnosticOutputList.replaceChildren();elements.diagnosticOutputRelease.hidden=true;if(!outputs)return;elements.diagnosticOutputList.append(renderDiagnosticOutput({artifact:"executive-brief",title:"Executive Capacity Brief",subtitle:"Sponsor-facing, concise, decision-oriented, and locked until deliberate release.",status:outputs.executiveBrief.reviewStatus,payload:outputs.executiveBrief.payload}),renderDiagnosticOutput({artifact:"revelation-guide",title:"Private Steward Revelation Guide",subtitle:"Your private talk track, evidence interpretation, uncertainty guidance, and discussion preparation.",status:outputs.revelationGuide.reviewStatus,payload:outputs.revelationGuide.payload}));if(outputs.executiveBrief.status==="released"){const access=outputs.executiveBrief.accessMode==="permanent"?"Permanent sponsor access":`POC access through ${new Date(outputs.executiveBrief.accessExpiresAt).toLocaleDateString()}`;elements.diagnosticOutputsMessage.textContent=`Executive Brief released · ${access} · Sponsor notification ready for delivery. The Revelation Guide remains private.`;return;}elements.diagnosticOutputRelease.hidden=!outputs.releaseReady;elements.diagnosticOutputsMessage.textContent=outputs.releaseReady?"Both outputs are approved. Schedule the Revelation Session, then use the deliberate release control below.":"Review and approve each output separately. Neither artifact has been released.";}
