async function loadSynthesis(progress){elements.synthesisSection.hidden=false;const data=await request(`/api/workspace/diagnostic-synthesis?diagnosticId=${encodeURIComponent(assignment.diagnosticId)}`);renderSynthesis(data.finding);elements.createSynthesis.hidden=Boolean(data.finding);elements.createSynthesis.disabled=progress.pending>0||progress.approved<2;elements.synthesisMessage.textContent=data.finding?.advisorReviewStatus==="approved"?"Steward-approved. Prepare the two governed outputs next.":data.finding?.advisorReviewStatus==="revision-required"?"Revision required. This finding cannot advance.":data.finding?"Draft created. Steward validation is the next gate.":progress.pending>0?"Review every evidence candidate before synthesis.":progress.approved<2?"Approve at least two evidence records before synthesis.":"Approved evidence is ready for a protected synthesis draft.";await loadDiagnosticOutputs(data.finding);}
async function loadIntervention(){const data=await request(`/api/workspace/diagnostic-intervention?diagnosticId=${encodeURIComponent(assignment.diagnosticId)}`);elements.interventionSection.hidden=false;elements.interventionForm.hidden=true;elements.interventionStatus.replaceChildren();if(data.state==="blocked"){elements.interventionMessage.textContent="Leadership validation must be accepted before intervention design becomes available.";return;}elements.interventionMessage.textContent=data.state==="poc-complete"?"POC complete. The governed Intervention Direction is ready for the final debrief. Detailed design, delivery, and reassessment begin only after paid activation.":data.state==="proposed"?"A governed intervention proposal has been created. Commercial acceptance is the next gate.":"The finding is leadership-validated. Governed intervention design is ready.";const card=document.createElement("article");const statement=document.createElement("p");statement.textContent=data.finding.statement;const direction=document.createElement("p");direction.textContent=`Starting direction: ${data.finding.interventionDirection}`;card.append(statement,direction);if(data.state==="poc-complete"){const boundary=document.createElement("strong");boundary.textContent="POC boundary reached · Paid activation is the next decision";card.append(boundary);}if(data.intervention){const detail=document.createElement("p");detail.textContent=`${data.intervention.serviceRoute} · ${data.intervention.proposal.duration} · ${data.intervention.status}`;card.append(detail);}elements.interventionStatus.append(card);elements.interventionForm.hidden=data.state!=="ready";}
async function loadEscalationQueue(){const data=await request(`/api/workspace/advisor-escalation-queue?diagnosticId=${encodeURIComponent(assignment.diagnosticId)}`);elements.escalationQueue.hidden=false;elements.escalationList.replaceChildren();for(const item of data.requests){const card=document.createElement("article"),title=document.createElement("strong"),context=document.createElement("p"),outcome=document.createElement("p");title.textContent=`${item.urgency} · ${item.supportType} · ${item.status}`;context.textContent=item.context;outcome.textContent=`Desired outcome: ${item.desiredOutcome}`;card.append(title,context,outcome);if(item.status!=="closed"){const form=document.createElement("form");form.dataset.escalationId=item.requestId;form.className="advisor-review";const note=document.createElement("input");note.name="note";note.minLength=20;note.maxLength=1200;note.required=true;note.placeholder="Record contact, next step, or closure rationale";for(const [status,label] of [["contacted","Mark contacted"],["closed","Close request"]]){const button=document.createElement("button");button.type="submit";button.value=status;button.textContent=label;form.append(button);}form.prepend(note);card.append(form);}else if(item.advisorNote){const note=document.createElement("p");note.textContent=`Advisor note: ${item.advisorNote}`;card.append(note);}elements.escalationList.append(card);}elements.escalationMessage.textContent=data.requests.length?`${data.requests.length} advisor-support request${data.requests.length===1?"":"s"} in this engagement history.`:"No advisor-support requests are attached to this diagnostic.";}
async function loadPocScorecard(){const data=await request(`/api/workspace/poc-scorecard?diagnosticId=${encodeURIComponent(assignment.diagnosticId)}`),value=data.scorecard;elements.pocScorecard.hidden=value.state!=="active";if(value.state!=="active")return;elements.pocScorecardSummary.replaceChildren(...[[value.participation.approvedSlots,"slots"],[value.participation.completed,"completed"],[value.participation.completionRate===null?"—":`${value.participation.completionRate}%`,"completion"],[value.evidence.approved,"approved evidence"],[value.operations.formalReviews,"formal reviews"]].map(([number,label])=>Object.assign(document.createElement("span"),{textContent:`${number} ${label}`})));const observed=new Set(value.feedback.map(row=>`${row.respondentRole}:${row.checkpoint}`));const checkpoints=[["participant:interview-completion","Participant experience","Optional, offered immediately after submission"],["sponsor:sponsor-setup","Sponsor setup","Capture after context and participant design"],["sponsor:finding-release","Finding release","Capture when the governed finding is reviewed"],["sponsor:final-debrief","Final debrief","Capture at the POC boundary"]];elements.pocLearningCheckpoints.replaceChildren(...checkpoints.map(([key,label,timing])=>{const card=document.createElement("article"),title=document.createElement("strong"),detail=document.createElement("p"),captured=observed.has(key);title.textContent=`${captured?"Captured":"Open"} · ${label}`;detail.textContent=timing;card.append(title,detail);return card;}));elements.pocScorecardDetail.replaceChildren();for(const row of value.feedback){const card=document.createElement("article"),title=document.createElement("strong"),metrics=document.createElement("p");title.textContent=`${row.respondentRole} · ${row.checkpoint} · ${row.responses} response${row.responses===1?"":"s"}`;metrics.textContent=`Clarity ${row.clarity??"—"} · Trust ${row.trust??"—"} · Actionability ${row.actionability??"—"} · Support required ${row.supportRequired} · Purchase yes/no/uncertain ${row.purchaseIntent.yes}/${row.purchaseIntent.no}/${row.purchaseIntent.uncertain}`;card.append(title,metrics);elements.pocScorecardDetail.append(card);}if(!value.feedback.length)elements.pocScorecardDetail.textContent="No optional checkpoint feedback has been captured yet.";elements.pocScorecardMessage.textContent=`${value.engagement.route} route · Method ${value.engagement.methodVersion} · Intervention ${value.operations.interventionStatus||"not accepted"} · Brief ${value.operations.briefActivated?"active":"not active"}`;}
async function loadPocDecisions(){const data=await request(`/api/workspace/poc-cohort-decisions?diagnosticId=${encodeURIComponent(assignment.diagnosticId)}`);elements.pocDecisions.hidden=false;elements.pocDecisionHistory.replaceChildren();for(const value of data.decisions){const card=document.createElement("article"),heading=document.createElement("strong"),rationale=document.createElement("p"),detail=document.createElement("p");heading.textContent=`${value.decision.replaceAll("-"," ")} · ${new Date(value.createdAt).toLocaleString()}`;rationale.textContent=value.rationale;detail.textContent=`Required changes ${value.requiredChanges.length} · Unresolved risks ${value.unresolvedRisks.length} · Next hypotheses ${value.nextHypotheses.length}${value.nextReviewAt?` · Review ${new Date(value.nextReviewAt).toLocaleString()}`:""}`;card.append(heading,rationale,detail);elements.pocDecisionHistory.append(card);}if(!data.decisions.length)elements.pocDecisionMessage.textContent="No cohort decision has been recorded yet.";}
function changeDecisionForm(candidateId){const form=document.createElement("form");form.dataset.changeDecision=candidateId;form.className="advisor-review";form.innerHTML=`<select name="decision"><option value="approved">Approve</option><option value="rejected">Reject</option><option value="deferred">Defer</option></select><input name="rationale" minlength="40" maxlength="1500" placeholder="Decision rationale" required /><button type="submit">Record decision</button>`;return form;}
function changeValidationForm(candidateId){const form=document.createElement("form");form.dataset.changeValidation=candidateId;form.className="advisor-synthesis-review";form.innerHTML=`<label>Result<select name="result"><option value="validated">Validated</option><option value="invalidated">Invalidated</option><option value="inconclusive">Inconclusive</option></select></label><label>Observed result<textarea name="observedResult" minlength="40" maxlength="1500" required></textarea></label><label>Assessment against measure<textarea name="measureAssessment" minlength="40" maxlength="1500" required></textarea></label><label><input type="checkbox" name="rollbackTriggered" /> Rollback condition triggered</label><label>Next action<textarea name="nextAction" minlength="20" maxlength="1000" required></textarea></label><button type="submit">Record validation result</button>`;return form;}
async function loadPocChanges(){const data=await request(`/api/workspace/poc-change-candidates?diagnosticId=${encodeURIComponent(assignment.diagnosticId)}`);elements.pocChanges.hidden=false;elements.pocChangeList.replaceChildren();for(const value of data.candidates){const card=document.createElement("article"),heading=document.createElement("strong"),problem=document.createElement("p"),change=document.createElement("p"),detail=document.createElement("small");heading.textContent=`${value.severity} · ${value.affectedRole} · ${value.decision?.decision||"awaiting decision"}`;problem.textContent=value.observedProblem;change.textContent=`Proposed change: ${value.proposedChange}`;detail.textContent=`Owner ${value.owner} · Target ${value.targetRelease} · ${value.validations.length} validation result${value.validations.length===1?"":"s"}`;card.append(heading,problem,change,detail);if(!value.decision||value.decision.decision==="deferred")card.append(changeDecisionForm(value.candidateId));else if(value.decision.decision==="approved")card.append(changeValidationForm(value.candidateId));for(const validation of value.validations){const result=document.createElement("p");result.textContent=`${validation.result} · ${validation.measureAssessment} · Next: ${validation.nextAction}${validation.rollbackTriggered?" · Rollback triggered":""}`;card.append(result);}elements.pocChangeList.append(card);}if(!data.candidates.length)elements.pocChangeMessage.textContent="No change candidates have been recorded.";}
function lines(value){return String(value||"").split(/\n+/).map(item=>item.trim()).filter(Boolean);}
async function loadComparisonAuthoring(){const data=await request(`/api/workspace/diagnostic-reassessment-comparison?followupDiagnosticId=${encodeURIComponent(assignment.diagnosticId)}`);elements.comparisonSection.hidden=data.state==="not-reassessment";elements.comparisonForm.hidden=data.state!=="ready";elements.comparisonThemes.replaceChildren();if(data.state==="not-reassessment")return;if(data.state==="ready"){elements.comparisonThemes.append(listSection("Available baseline themes",data.baselineThemeTitles),listSection("Available reassessment themes",data.followupThemeTitles));elements.comparisonMessage.textContent="All release gates are ready. Cite exact governed theme titles in the comparison.";}else elements.comparisonMessage.textContent=data.state==="released"?"The governed comparison has been released to the client workspace.":"Comparison remains blocked until both findings receive advisor and leadership validation.";}
async function loadQueue(){const data=await request(`/api/workspace/diagnostic-evidence-review?diagnosticId=${encodeURIComponent(assignment.diagnosticId)}`);elements.progress.replaceChildren(...[[data.progress.pending,"Pending"],[data.progress.approved,"Approved"],[data.progress.excluded,"Excluded"],[data.progress.highRiskPending,"High-risk review"]].map(([count,label])=>Object.assign(document.createElement("span"),{textContent:`${count} ${label}`})));elements.evidence.replaceChildren();for(const record of data.evidence){const card=document.createElement("article");const heading=document.createElement("strong");heading.textContent=`Evidence from ${record.sourceQuestionId} · ${record.reviewStatus}`;const quote=document.createElement("blockquote");quote.textContent=record.deidentifiedText;const footer=document.createElement("footer");footer.textContent=`Privacy handling complete · ${record.disclosureRisk} disclosure risk`;card.append(heading,quote,footer);if(record.reviewStatus==="pending"){const form=document.createElement("form");form.className="advisor-review";form.dataset.evidenceId=record.evidenceId;const note=document.createElement("input");note.placeholder="Why should this evidence be excluded?";note.maxLength=500;const approve=document.createElement("button");approve.type="submit";approve.name="decision";approve.value="approved";approve.textContent="Safe to use";const exclude=document.createElement("button");exclude.type="submit";exclude.name="decision";exclude.value="excluded";exclude.textContent="Exclude";form.append(note,approve,exclude);card.append(form);}elements.evidence.append(card);}await loadSynthesis(data.progress);}
async function loadStewardSessions(){const data=await request(`/api/workspace/diagnostic-steward-sessions?diagnosticId=${encodeURIComponent(assignment.diagnosticId)}`);elements.stewardSessionList.replaceChildren();for(const value of data.sessions){const card=document.createElement("article"),title=document.createElement("strong"),detail=document.createElement("p");title.textContent=`${value.sessionType} · ${value.status}`;detail.textContent=new Date(value.scheduledAt).toLocaleString();card.append(title,detail);if(value.status==="scheduled"){const form=document.createElement("form");form.dataset.completeSession=value.sessionType;const note=document.createElement("textarea");note.name="completionNote";note.minLength=30;note.maxLength=1000;note.required=true;note.placeholder="What was completed and what governing decision can now advance?";const button=document.createElement("button");button.type="submit";button.textContent="Record session complete";form.append(note,button);card.append(form);}elements.stewardSessionList.append(card);}elements.stewardSessionMessage.textContent=data.sessions.length?`${data.sessions.length} governed session record${data.sessions.length===1?"":"s"}.`:"The sponsor has not yet recorded a session booking.";}
let currentGovernedStage="command";const stewardStages=[{id:"command",label:"Understand the engagement"},{id:"frame",label:"Shape the inquiry"},{id:"protocol",label:"Prepare the questions"},{id:"evidence",label:"Protect the evidence"},{id:"synthesis",label:"Prepare the revelation"}];const stageForAction=code=>["complete-guidance","approve-context","complete-design"].includes(code)?"frame":["approve-perspectives","prepare-protocol","sponsor-protocol-review","finalize-protocol","activate-collection"].includes(code)?"protocol":["invite-perspectives","reach-threshold","resolve-collection","prepare-evidence","review-evidence"].includes(code)?"evidence":["synthesize","review-synthesis","prepare-intervention-directions","review-intervention-directions","revise-intervention-directions","prepare-dual-outputs","review-dual-outputs","revise-dual-outputs","schedule-revelation","release-executive-brief","prepare-revelation","advance"].includes(code)?"synthesis":"command";
const stewardGuidance={command:{title:"See the engagement state before intervening.",why:"The command center minimizes operational signals into the one governed move most likely to protect momentum.",uncertainty:"A stalled invitation or incomplete interview does not reveal participant sentiment or diagnostic evidence.",receipt:"Your time-bounded assignment and tenant-scoped engagement are confirmed.",next:"Open the stage currently requiring steward attention.",primarySelector:"[data-open-current-stage]"},frame:{title:"Shape an inquiry that can be tested without deciding the answer.",why:"A precise execution demand and evidence boundary protect both relevance and neutrality.",uncertainty:"Sponsor context remains a hypothesis source until multi-perspective evidence confirms, challenges, or complicates it.",receipt:"The sponsor’s approved context is retained as a versioned starting point.",next:"Review the frame and complete the next governance decision.",primarySelector:"#advisor-stage-frame",reviewSelector:"[data-stage-button=command]"},protocol:{title:"Protect one comparable question set for every participant.",why:"Consistency allows differences across vantage points to become evidence rather than questionnaire noise.",uncertainty:"Question coverage can support inquiry; it cannot guarantee a specific finding.",receipt:"Sponsor review and steward finalization remain separate, auditable decisions.",next:"Review protocol readiness and resolve the next open gate.",primarySelector:"#advisor-stage-protocol",reviewSelector:"[data-stage-button=frame]"},evidence:{title:"Decide what is safe and strong enough to enter synthesis.",why:"Disclosure review and evidence sufficiency are both required before an organizational pattern can be used.",uncertainty:"De-identification reduces disclosure risk; it does not make re-identification impossible in every context.",receipt:"Only prepared, de-identified evidence candidates enter this steward view.",next:"Review every pending evidence candidate.",primarySelector:"#advisor-stage-evidence",reviewSelector:"[data-stage-button=protocol]"},synthesis:{title:"Prepare an executive finding that makes reasoning and uncertainty inspectable.",why:"The sponsor needs clear direction without false certainty or premature intervention claims.",uncertainty:"Evidence-informed Intervention Directions are not empirically predictive and do not prove causality.",receipt:"Finding, Executive Brief, and private Revelation Guide require separate approval and release decisions.",next:"Complete the next synthesis or revelation gate.",primarySelector:"#advisor-stage-synthesis",reviewSelector:"[data-stage-button=evidence]"}};
function expandNarratives(scope=document){for(const textarea of scope.querySelectorAll("textarea")){textarea.style.height="auto";textarea.style.height=`${textarea.scrollHeight}px`;}}
function showStage(stage,{focus=false}={}){const selected=elements.stageViews.some(view=>view.dataset.advisorStage===stage)?stage:"command",view=document.querySelector(`[data-advisor-stage="${selected}"]`),index=stewardStages.findIndex(item=>item.id===selected);for(const item of elements.stageViews)item.hidden=item!==view;for(const button of elements.stageButtons)button.setAttribute("aria-selected",String(button.dataset.stageButton===selected));elements.journeyPosition.textContent=`Step ${index+1} of ${stewardStages.length}`;elements.journeyLabel.textContent=stewardStages[index].label;elements.journeyProgress.style.width=`${((index+1)/stewardStages.length)*100}%`;if(history.replaceState)history.replaceState(null,"",`#${selected}`);requestAnimationFrame(()=>expandNarratives(view));if(!elements.console.hidden){const guidance=stewardGuidance[selected];window.capacityGuidance?.({role:"steward",position:`Step ${index+1} of ${stewardStages.length} · Decision guidance`,...guidance,primaryLabel:"Open current work",reviewLabel:"Review prior gate"});}if(focus)view?.scrollIntoView({behavior:"smooth",block:"start"});}
function markCurrentStage(stage){currentGovernedStage=stage;elements.engagementStage.textContent=stage.replaceAll("-"," ");for(const button of elements.stageButtons)button.dataset.current=String(button.dataset.stageButton===stage);}
async function loadCommandCenter(){elements.commandMessage.textContent="Refreshing minimized operating intelligence…";try{const data=await request(`/api/workspace/steward-command-center?diagnosticId=${encodeURIComponent(assignment.diagnosticId)}`);elements.commandNextAction.textContent=data.nextAction.label;elements.commandNextOwner.textContent=`Owner: ${data.nextAction.owner.replaceAll("-"," ")}`;markCurrentStage(stageForAction(data.nextAction.code));elements.commandProgress.replaceChildren(...[[data.progress.planned,"planned"],[data.progress.invited,"invited"],[data.progress.invitationAccepted,"accepted invite"],[data.progress.noticeAccepted,"started"],[data.progress.completed,"completed"]].map(([number,label])=>Object.assign(document.createElement("span"),{textContent:`${number} ${label}`})));elements.commandParticipants.replaceChildren();for(const item of data.participants){const row=document.createElement("article"),identity=document.createElement("div"),email=document.createElement("strong"),slot=document.createElement("small"),state=document.createElement("span");email.textContent=item.emailAddress||"Invitation identity unavailable";slot.textContent=item.needsFollowUp?item.attentionReason:item.planSlotId;state.textContent=item.needsFollowUp?`Follow up · ${item.stage.replaceAll("-"," ")}`:item.stage.replaceAll("-"," ");state.dataset.stage=item.stage;row.dataset.attention=String(item.needsFollowUp);identity.append(email,slot);row.append(identity,state);elements.commandParticipants.append(row);}if(!data.participants.length)elements.commandParticipants.textContent="No participant invitations have been recorded.";elements.commandThreshold.replaceChildren();const threshold=document.createElement("article"),title=document.createElement("strong"),copy=document.createElement("p");title.textContent=data.threshold.met?"Confidentiality threshold met":`${data.threshold.completed} of ${data.threshold.minimum} required completions`;copy.textContent=data.emergingIntelligence.message;threshold.dataset.met=String(data.threshold.met);threshold.append(title,copy);elements.commandThreshold.append(threshold);elements.commandClusters.replaceChildren();for(const cluster of data.emergingIntelligence.clusters){const chip=document.createElement("span");chip.textContent=`${cluster.mechanismId.replaceAll("-"," ")} · ${cluster.evidenceCount}`;elements.commandClusters.append(chip);}for(const theme of data.emergingIntelligence.themes){const card=document.createElement("article"),name=document.createElement("strong"),summary=document.createElement("p");name.textContent=`${theme.title} · ${theme.confidence}`;summary.textContent=theme.summary;card.append(name,summary);elements.commandClusters.append(card);}elements.commandMessage.textContent=`Evidence review: ${data.evidence.pending} pending · ${data.evidence.approved} approved · ${data.evidence.highRiskPending} high-risk pending.`;}catch(error){elements.commandMessage.textContent=error.message;}}
async function loadAssignments(){const data=await request("/api/workspace/diagnostic-advisor-assignments");if(data.assignments.length){assignment=data.assignments[0];elements.console.hidden=false;assignmentCard(assignment);await loadCommandCenter();await loadStewardSessions();await loadFrame();await loadProtocolV2();await loadQueue();showStage(location.hash.slice(1)||currentGovernedStage);return;}elements.console.hidden=true;elements.status.textContent="No active advisor assignment is available. A Senger Advisory platform operator must grant time-bounded access.";}
async function initialize(){try{const config=await request("/api/workspace/config");await script(config.clerkUiUrl);await script(config.clerkJsUrl,config.publishableKey);clerk=window.Clerk;await clerk.load({ui:{ClerkUI:window.__internal_ClerkUICtor}});if(!clerk.user){elements.status.textContent="Sign in to continue.";clerk.mountSignIn(elements.signIn,{forceRedirectUrl:"/workspace/advisor.html",fallbackRedirectUrl:"/workspace/advisor.html",signUpForceRedirectUrl:"/workspace/advisor.html",signUpFallbackRedirectUrl:"/workspace/advisor.html"});return;}elements.signOut.hidden=false;if(!(await activeOrganization()))throw new Error("Open a valid organization invitation before advisor access.");session=await request("/api/workspace/session");elements.status.textContent="Advisor authority is checked separately from your client workspace role.";await loadAssignments();}catch(error){elements.status.textContent=error.message;}}
