elements.stewardSessionList.addEventListener("submit",async event=>{event.preventDefault();const form=event.target.closest("[data-complete-session]");if(!form||!form.reportValidity())return;const button=form.querySelector("button");button.disabled=true;try{await request("/api/workspace/diagnostic-steward-sessions",{method:"PATCH",body:{diagnosticId:assignment.diagnosticId,sessionType:form.dataset.completeSession,completionNote:form.elements.completionNote.value}});await Promise.all([loadStewardSessions(),loadCommandCenter()]);}catch(error){elements.stewardSessionMessage.textContent=error.message;button.disabled=false;}});
