elements.prepare.addEventListener("click",async()=>{elements.prepare.disabled=true;elements.preparationMessage.textContent="Preparing one submitted interview through protected de-identification…";try{const result=await request("/api/workspace/diagnostic-evidence-preparation",{method:"POST",body:{diagnosticId:assignment.diagnosticId}});elements.preparationMessage.textContent=result.queueEmpty?"No unprepared submitted interviews remain.":`${result.evidenceCount} evidence candidates prepared for review.`;await loadQueue();}catch(error){elements.preparationMessage.textContent=error.message;}finally{elements.prepare.disabled=false;}});
