elements.createSynthesis.addEventListener("click",async()=>{elements.createSynthesis.disabled=true;elements.synthesisMessage.textContent="Synthesizing approved de-identified evidence…";try{const data=await request("/api/workspace/diagnostic-synthesis",{method:"POST",body:{diagnosticId:assignment.diagnosticId}});renderSynthesis(data.finding);elements.createSynthesis.hidden=true;elements.synthesisMessage.textContent="Draft created. Advisor validation is the next gate.";}catch(error){elements.synthesisMessage.textContent=error.message;elements.createSynthesis.disabled=false;}});
