elements.createInterventionDirections.addEventListener("click",async()=>{elements.createInterventionDirections.disabled=true;elements.interventionDirectionsMessage.textContent="Preparing three evidence-informed, vendor-neutral directions…";try{const data=await request("/api/workspace/diagnostic-intervention-directions",{method:"POST",body:{diagnosticId:assignment.diagnosticId}});elements.createInterventionDirections.hidden=true;renderInterventionDirections(data.directions);}catch(error){elements.interventionDirectionsMessage.textContent=error.message;elements.createInterventionDirections.disabled=false;}});
elements.interventionDirectionsReview.addEventListener("submit",async event=>{event.preventDefault();const submitter=event.submitter;if(!submitter)return;for(const button of elements.interventionDirectionsReview.querySelectorAll("button"))button.disabled=true;try{const data=await request("/api/workspace/diagnostic-intervention-directions",{method:"PATCH",body:{diagnosticId:assignment.diagnosticId,decision:submitter.value,reviewNote:elements.interventionDirectionsReview.elements.reviewNote.value}});renderInterventionDirections(data.directions);await Promise.all([loadDiagnosticOutputs({advisorReviewStatus:"approved"}),loadCommandCenter()]);}catch(error){elements.interventionDirectionsMessage.textContent=error.message;for(const button of elements.interventionDirectionsReview.querySelectorAll("button"))button.disabled=false;}});
elements.createDiagnosticOutputs.addEventListener("click",async()=>{elements.createDiagnosticOutputs.disabled=true;elements.diagnosticOutputsMessage.textContent="Preparing the locked Brief and private Revelation Guide…";try{const data=await request("/api/workspace/diagnostic-dual-outputs",{method:"POST",body:{diagnosticId:assignment.diagnosticId}});elements.createDiagnosticOutputs.hidden=true;renderDiagnosticOutputs(data.outputs);}catch(error){elements.diagnosticOutputsMessage.textContent=error.message;elements.createDiagnosticOutputs.disabled=false;}});
elements.diagnosticOutputList.addEventListener("submit",async event=>{event.preventDefault();const form=event.target.closest("[data-output-review]"),submitter=event.submitter;if(!form||!submitter)return;for(const button of form.querySelectorAll("button"))button.disabled=true;try{const data=await request("/api/workspace/diagnostic-dual-outputs",{method:"PATCH",body:{diagnosticId:assignment.diagnosticId,artifact:form.dataset.outputReview,decision:submitter.value,reviewNote:form.elements.reviewNote.value}});renderDiagnosticOutputs(data.outputs);await loadCommandCenter();}catch(error){elements.diagnosticOutputsMessage.textContent=error.message;for(const button of form.querySelectorAll("button"))button.disabled=false;}});
elements.releaseExecutiveBrief.addEventListener("click",async()=>{elements.releaseExecutiveBrief.disabled=true;elements.diagnosticOutputsMessage.textContent="Checking collection, confidentiality, output approval, and Revelation scheduling gates…";try{const data=await request("/api/workspace/diagnostic-executive-brief",{method:"POST",body:{diagnosticId:assignment.diagnosticId}});elements.diagnosticOutputRelease.hidden=true;const access=data.brief.access.permanent?"Permanent sponsor access":`Sponsor access and download through ${new Date(data.brief.access.expiresAt).toLocaleDateString()}`;elements.diagnosticOutputsMessage.textContent=`Executive Capacity Brief released · ${access}. Sponsor notification is ready for delivery; the Revelation Guide remains private.`;await Promise.all([loadDiagnosticOutputs({advisorReviewStatus:"approved"}),loadCommandCenter()]);}catch(error){elements.diagnosticOutputsMessage.textContent=error.message;elements.releaseExecutiveBrief.disabled=false;}});
elements.comparisonForm.addEventListener("submit",async event=>{event.preventDefault();if(!elements.comparisonForm.reportValidity())return;const values=Object.fromEntries(new FormData(elements.comparisonForm)),button=elements.comparisonForm.querySelector("button");button.disabled=true;elements.comparisonMessage.textContent="Verifying comparability, confidentiality, and evidence trace…";try{await request("/api/workspace/diagnostic-reassessment-comparison",{method:"POST",body:{followupDiagnosticId:assignment.diagnosticId,changeAssessment:values.changeAssessment,changed:values.changed,persisted:values.persisted,emerged:values.emerged,uncertainty:values.uncertainty,leadershipImplication:values.leadershipImplication,baselineThemeTitles:lines(values.baselineThemeTitles),followupThemeTitles:lines(values.followupThemeTitles)}});elements.comparisonForm.hidden=true;elements.comparisonMessage.textContent="Governed comparison released. No causal claim was created.";}catch(error){elements.comparisonMessage.textContent=error.message;button.disabled=false;}});
elements.interventionForm.addEventListener("submit",async event=>{event.preventDefault();if(!elements.interventionForm.reportValidity())return;const values=Object.fromEntries(new FormData(elements.interventionForm));const button=elements.interventionForm.querySelector("button[type=submit]");button.disabled=true;elements.interventionFormMessage.textContent="Creating the governed intervention proposal…";try{await request("/api/workspace/diagnostic-intervention",{method:"POST",body:{diagnosticId:assignment.diagnosticId,serviceRoute:values.serviceRoute,objective:values.objective,rationale:values.rationale,scope:values.scope,operatingChanges:lines(values.operatingChanges),commitments:[{action:values.commitmentAction,ownerRole:values.commitmentOwnerRole,timing:values.commitmentTiming}],learningRequirements:lines(values.learningRequirements),evidencePlan:[{evidenceClass:"delivery",measure:values.deliveryMeasure,observationCadence:values.deliveryCadence},{evidenceClass:"operating-change",measure:values.operatingMeasure,observationCadence:values.operatingCadence},{evidenceClass:"capacity-change",measure:values.capacityMeasure,observationCadence:values.capacityCadence}],reviewCadence:values.reviewCadence,duration:values.duration,commercialOfferRef:values.commercialOfferRef}});elements.interventionFormMessage.textContent="Proposal created. Client review and commercial acceptance are the next gates.";await loadIntervention();}catch(error){elements.interventionFormMessage.textContent=error.message;button.disabled=false;}});
elements.escalationList.addEventListener("submit",async event=>{event.preventDefault();const form=event.target.closest("[data-escalation-id]"),submitter=event.submitter;if(!form||!submitter||!form.reportValidity())return;submitter.disabled=true;try{await request("/api/workspace/advisor-escalation-queue",{method:"PATCH",body:{diagnosticId:assignment.diagnosticId,requestId:form.dataset.escalationId,status:submitter.value,note:form.elements.note.value}});await loadEscalationQueue();}catch(error){elements.escalationMessage.textContent=error.message;submitter.disabled=false;}});
elements.pocDecisionForm.addEventListener("submit",async event=>{event.preventDefault();if(!elements.pocDecisionForm.reportValidity())return;const values=Object.fromEntries(new FormData(elements.pocDecisionForm)),button=elements.pocDecisionForm.querySelector("button");button.disabled=true;elements.pocDecisionMessage.textContent="Recording the evidence-backed cohort decision…";try{await request("/api/workspace/poc-cohort-decisions",{method:"POST",body:{diagnosticId:assignment.diagnosticId,decision:values.decision,rationale:values.rationale,requiredChanges:lines(values.requiredChanges),unresolvedRisks:lines(values.unresolvedRisks),nextHypotheses:lines(values.nextHypotheses),nextReviewAt:values.nextReviewAt?new Date(values.nextReviewAt).toISOString():null}});elements.pocDecisionForm.reset();elements.pocDecisionMessage.textContent="Cohort decision recorded in immutable product history.";await loadPocDecisions();}catch(error){elements.pocDecisionMessage.textContent=error.message;}finally{button.disabled=false;}});
elements.pocChangeForm.addEventListener("submit",async event=>{event.preventDefault();if(!elements.pocChangeForm.reportValidity())return;const formData=new FormData(elements.pocChangeForm),values=Object.fromEntries(formData),button=elements.pocChangeForm.querySelector("button[type=submit]");button.disabled=true;try{await request("/api/workspace/poc-change-candidates",{method:"POST",body:{action:"create-candidate",diagnosticId:assignment.diagnosticId,cohortDecisionId:null,observedProblem:values.observedProblem,affectedRole:values.affectedRole,evidenceSummary:values.evidenceSummary,frequencySummary:values.frequencySummary,severity:values.severity,riskOfNoChange:values.riskOfNoChange,proposedChange:values.proposedChange,owner:values.owner,targetRelease:values.targetRelease,validationMeasure:values.validationMeasure,rollbackCondition:values.rollbackCondition,governanceImpacts:formData.getAll("governanceImpacts")}});elements.pocChangeForm.reset();elements.pocChangeMessage.textContent="Change candidate recorded for explicit review.";await loadPocChanges();}catch(error){elements.pocChangeMessage.textContent=error.message;}finally{button.disabled=false;}});
elements.pocChangeList.addEventListener("submit",async event=>{event.preventDefault();const decisionForm=event.target.closest("[data-change-decision]"),validationForm=event.target.closest("[data-change-validation]");if(!event.target.reportValidity())return;const values=Object.fromEntries(new FormData(event.target)),button=event.target.querySelector("button");button.disabled=true;try{if(decisionForm)await request("/api/workspace/poc-change-candidates",{method:"POST",body:{action:"decide-candidate",diagnosticId:assignment.diagnosticId,candidateId:decisionForm.dataset.changeDecision,decision:values.decision,rationale:values.rationale}});else if(validationForm)await request("/api/workspace/poc-change-candidates",{method:"POST",body:{action:"record-validation",diagnosticId:assignment.diagnosticId,candidateId:validationForm.dataset.changeValidation,result:values.result,observedResult:values.observedResult,measureAssessment:values.measureAssessment,rollbackTriggered:Boolean(values.rollbackTriggered),nextAction:values.nextAction}});await loadPocChanges();}catch(error){elements.pocChangeMessage.textContent=error.message;button.disabled=false;}});
elements.frameForm.addEventListener("submit",async event=>{event.preventDefault();if(!elements.frameForm.reportValidity())return;const formData=new FormData(elements.frameForm),values=Object.fromEntries(formData),button=elements.frameForm.querySelector("button[type=submit]");button.disabled=true;elements.frameMessage.textContent="Validating the execution demand, complexity coverage, and evidence boundary…";try{const complexityObservations=complexityDimensions.map((dimension,index)=>({observationId:`${assignment.diagnosticId}-${dimension}`,source:"Approved sponsor context and advisor framing",description:values[`complexity-${dimension}`],dimensions:[dimension],state:"current-and-anticipated",classification:values[`classification-${dimension}`],classificationRationale:values[`classification-${dimension}`]==="undetermined"?"Classification remains open pending participant and operating evidence.":"Advisor hypothesis based on approved sponsor context; participant and operating evidence must confirm or challenge it.",evidenceRefs:[],confidence:"limited",confidenceBasis:"The frame uses approved sponsor context; multi-perspective collection has not yet tested this observation."}));const sourceTypes=["sponsor-discovery","participant-interview",...formData.getAll("sourceTypes")];const data=await request("/api/workspace/diagnostic-frame-v2",{method:"POST",body:{diagnosticId:assignment.diagnosticId,organizationContext:values.organizationContext,executionDemand:{commitment:values.commitment,successDefinition:values.successDefinition,failureExposure:values.failureExposure,timeHorizon:values.timeHorizon},diagnosticQuestion:values.diagnosticQuestion,leadershipDecision:values.leadershipDecision,performanceConsequences:textLines(values.performanceConsequences),complexityObservations,evidencePlan:{sourceTypes,participantSlots:initialParticipantSlots,formalArtifactsRequested:textLines(values.formalArtifactsRequested),operatingDataRequested:textLines(values.operatingDataRequested),acceptedCoverageGaps:[]},outOfScope:textLines(values.outOfScope),knownSensitivities:values.knownSensitivities,approvalNote:values.approvalNote,confirmedExecutionDemand:formData.has("confirmedExecutionDemand"),acceptedEvidencePlan:formData.has("acceptedEvidencePlan")}});renderFrame(data.frame);elements.frameMessage.textContent="Diagnostic inquiry approved. No finding has been released.";await loadProtocolV2();}catch(error){elements.frameMessage.textContent=error.message;button.disabled=false;}});
elements.protocolV2Form.addEventListener("submit",async event=>{event.preventDefault();if(!elements.protocolV2Form.reportValidity())return;const formData=new FormData(elements.protocolV2Form),button=elements.protocolV2Form.querySelector("button[type=submit]");button.disabled=true;elements.protocolV2Message.textContent="Checking evidence coverage and question sufficiency…";try{const questions=[...elements.protocolV2Questions.querySelectorAll("[data-template-id]")].map(card=>({templateId:card.dataset.templateId,questionText:card.querySelector("textarea").value,contextualizationNote:"Advisor reviewed against the approved Diagnostic Frame."}));const data=await request("/api/workspace/diagnostic-protocol-v2",{method:"POST",body:{diagnosticId:assignment.diagnosticId,questions,approvalNote:formData.get("approvalNote"),acceptedResearchLimitations:formData.has("acceptedResearchLimitations")}});renderProtocolV2(data.protocol);elements.protocolV2Message.textContent="Participant question set approved. Collection remains inactive until platform activation.";}catch(error){elements.protocolV2Message.textContent=error.message;button.disabled=false;}});
elements.protocolV2Finalization.addEventListener("submit",async event=>{event.preventDefault();if(!elements.protocolV2Finalization.reportValidity())return;const button=elements.protocolV2Finalization.querySelector("button[type=submit]"),formData=new FormData(elements.protocolV2Finalization);button.disabled=true;elements.protocolV2FinalizationMessage.textContent="Locking the sponsor-approved protocol for controlled collection…";try{await request("/api/workspace/diagnostic-protocol-v2",{method:"PATCH",body:{diagnosticId:assignment.diagnosticId,approvalNote:formData.get("approvalNote")}});elements.protocolV2Finalization.reset();await Promise.all([loadProtocolV2(),loadCommandCenter()]);elements.protocolV2FinalizationMessage.textContent="The exact 18-question protocol is finalized. Platform Operations may now activate collection.";}catch(error){elements.protocolV2FinalizationMessage.textContent=error.message;button.disabled=false;}});
